from pathlib import Path
import json

root = Path(__file__).resolve().parents[1]
data = json.loads((root / 'content/learner-support.json').read_text())
template = Path(__file__).with_name('learner-support.js').read_text()
(root / 'dist/learner-support.js').write_text(
    '/* Generated by scripts/build-learner-support.py. */\nconst learnerSupport='
    + json.dumps(data, ensure_ascii=False, indent=1) + ';\n' + template)
print(f"Built learner guide, {len(data['topics'])} self-check topics and {len(data['cases'])} cases.")
